//! Dialect v0.6 expressions: grammar, folding and policy analysis, checked against the Python reference
//! (../expr_vectors.json, generated by drivers/gen_expr_vectors.py) and the Python parser tests.
//! No server needed.
use serde_json::Value;
use torusdb::*;

mod common;
use common::col;

fn vec_json() -> Value {
    serde_json::from_str(&std::fs::read_to_string(common::expr_vectors_path()).unwrap()).unwrap()
}

fn scope_of(v: &Value, name: &str) -> Vec<(String, Vec<Column>)> {
    v["scopes"][name]
        .as_array()
        .unwrap()
        .iter()
        .map(|inst| {
            let alias = inst[0].as_str().unwrap().to_string();
            let cols = inst[1]
                .as_array()
                .unwrap()
                .iter()
                .map(|c| col(c[0].as_str().unwrap(), c[1].as_str().unwrap(), c[2].as_str().unwrap()))
                .collect();
            (alias, cols)
        })
        .collect()
}

/// Resolver over a scope spec, like the engine planner's.
pub fn resolver(scope: Vec<(String, Vec<Column>)>) -> impl Fn(&str) -> Result<Column, Error> {
    move |r: &str| {
        if let Some((inst, c)) = r.split_once('.') {
            let Some((_, cols)) = scope.iter().find(|(n, _)| n == inst) else {
                return Err(Error::new(Kind::PlanError, format!("unknown table '{}' in column ref '{}'", inst, r)));
            };
            return cols
                .iter()
                .find(|x| x.name == c)
                .cloned()
                .ok_or_else(|| Error::new(Kind::PlanError, format!("no such column: '{}' in table '{}'", c, inst)));
        }
        let owners: Vec<&(String, Vec<Column>)> = scope.iter().filter(|(_, cols)| cols.iter().any(|x| x.name == r)).collect();
        match owners.len() {
            1 => Ok(owners[0].1.iter().find(|x| x.name == r).unwrap().clone()),
            0 => Err(Error::new(Kind::PlanError, format!("no such column: '{}'", r))),
            _ => Err(Error::new(Kind::PlanError, format!("column '{}' is ambiguous in join — qualify as table.col", r))),
        }
    }
}

#[test]
fn static_vectors_match_the_python_reference() {
    let v = vec_json();
    let cases = v["static"].as_array().unwrap();
    assert!(cases.len() > 400, "only {} static vectors", cases.len());
    for c in cases {
        let text = c["expr"].as_str().unwrap();
        let r = resolver(scope_of(&v, c["scope"].as_str().unwrap()));
        let what = format!("{}: {:?}", c["scope"], text.chars().take(80).collect::<String>());
        let tree = match parse_expression(text) {
            Ok(t) => t,
            Err(e) => {
                assert_eq!(c["error"].as_str(), Some("ParseError"), "{}: {}", what, e);
                assert_eq!(e.kind, Kind::Parse, "{}: {}", what, e);
                continue;
            }
        };
        // An expression referencing an FHE column is analyzed through a separate path
        // (`fhe_expr::analyze_fhe_expr`), dispatched upstream of `analyze_expression` exactly like
        // the Python reference's unified `torussql_parser.expr.analyze_expr` (`fhe_ok=True` default,
        // see `Client::expr_plan` for the Rust mirror). `analyze_expression` on its own keeps
        // rejecting a bare FHE column reference by design (the low-level analyzer Python's
        // `fhe_ok=False` / `_an()` corresponds to) - this is what the vectors file's lone FHE "ok"
        // case now exercises (v0.6.2: `SUM(f*f)` is accepted, `REJECT_BARE_COLUMN_PRODUCT = false`).
        if references_fhe_column(&tree, &r).unwrap_or(false) {
            let out = analyze_fhe_expr(&tree, &r);
            match c["error"].as_str() {
                Some("PlanError") => {
                    let e = out.expect_err(&what);
                    assert_eq!(e.kind, Kind::PlanError, "{}: {}", what, e);
                    assert_eq!(e.message, c["message"].as_str().unwrap(), "{}", what);
                }
                Some(other) => panic!("{}: unexpected error kind {:?} for an FHE-column expression", what, other),
                None => {
                    let fx = out.unwrap_or_else(|e| panic!("{}: {}", what, e));
                    // no row-level FHE projection vectors exist today (see the task report); this port
                    // only reaches aggregate plans, so `analyze_fhe_expr` never returns a row-level one.
                    assert_eq!(render_expr(&tree), c["text"].as_str().unwrap(), "{}", what);
                    assert_eq!("agg", c["kind"].as_str().unwrap(), "{}", what);
                    assert!(c["enc"].as_bool().unwrap(), "{}", what);
                    assert_eq!(0, c["depth"].as_u64().unwrap(), "{}", what);
                    assert_eq!(fx.products as u64, c["ct_muls"].as_u64().unwrap(), "{}", what);
                    assert_eq!(0, c["inversions"].as_u64().unwrap(), "{}", what);
                }
            }
            continue;
        }
        let out = analyze_expression(&tree, &r);
        match c["error"].as_str() {
            Some("PlanError") => {
                let e = out.expect_err(&what);
                assert_eq!(e.kind, Kind::PlanError, "{}: {}", what, e);
                assert_eq!(e.message, c["message"].as_str().unwrap(), "{}", what);
            }
            _ => {
                let (folded, info) = out.unwrap_or_else(|e| panic!("{}: {}", what, e));
                assert_eq!(info.text, c["text"].as_str().unwrap(), "{}", what);
                assert_eq!(info.kind, c["kind"].as_str().unwrap(), "{}", what);
                assert_eq!(info.enc, c["enc"].as_bool().unwrap(), "{}", what);
                assert_eq!(info.depth as u64, c["depth"].as_u64().unwrap(), "{}", what);
                assert_eq!(info.ct_muls as u64, c["ct_muls"].as_u64().unwrap(), "{}", what);
                assert_eq!(info.inversions as u64, c["inversions"].as_u64().unwrap(), "{}", what);
                assert_eq!(render_expr(&folded), c["text"].as_str().unwrap(), "{}", what);
            }
        }
    }
}

// ── the Python parser tests (parser/tests/test_expr.py), on the AST ──
fn c(n: &str) -> Expr {
    Expr::Col(n.into())
}
fn l(n: i64, d: i64) -> Expr {
    Expr::Lit(Frac::new(n.into(), d.into()))
}
fn b(op: char, x: Expr, y: Expr) -> Expr {
    Expr::Bin(op, Box::new(x), Box::new(y))
}
fn neg(x: Expr) -> Expr {
    Expr::Neg(Box::new(x))
}
fn agg(f: &'static str, x: Option<Expr>) -> Expr {
    Expr::Agg(f, x.map(Box::new))
}
fn p(t: &str) -> Expr {
    parse_expression(t).unwrap_or_else(|e| panic!("{:?}: {}", t, e))
}
fn parse_kind(t: &str) -> Kind {
    parse_expression(t).expect_err(t).kind
}

#[test]
fn precedence_and_left_associativity() {
    assert_eq!(p("a+b*c"), b('+', c("a"), b('*', c("b"), c("c"))));
    assert_eq!(p("a-b-c"), b('-', b('-', c("a"), c("b")), c("c")));
    assert_eq!(p("a/b/c"), b('/', b('/', c("a"), c("b")), c("c")));
    assert_eq!(p("a*b/c"), b('/', b('*', c("a"), c("b")), c("c")));
    assert_eq!(p("(a+b)*c"), b('*', b('+', c("a"), c("b")), c("c")));
    assert_eq!(p("a*b*c"), b('*', b('*', c("a"), c("b")), c("c")));
}

#[test]
fn unary_minus_and_signed_literals() {
    assert_eq!(p("-a"), neg(c("a")));
    assert_eq!(p("-(a+b)"), neg(b('+', c("a"), c("b"))));
    assert_eq!(p("a * -b"), b('*', c("a"), neg(c("b"))));
    assert_eq!(p("a - -1"), b('-', c("a"), l(-1, 1)));
    assert_eq!(p("a*-2"), b('*', c("a"), l(-2, 1)));
    assert_eq!(p("-(-a)"), neg(neg(c("a"))));
    assert_eq!(p("- 3 * a + b"), b('+', b('*', l(-3, 1), c("a")), c("b")));
}

#[test]
fn a_negative_literal_token_in_operator_position_is_a_subtraction() {
    for t in ["a-1", "a -1", "a - 1", "a-1*b", "x*y-2", "(a)-1"] {
        assert!(matches!(p(t), Expr::Bin('-', ..)), "{}", t);
    }
    assert_eq!(p("a-2*b"), b('-', c("a"), b('*', l(2, 1), c("b"))));
    assert_eq!(p("a--1"), c("a")); // `--` starts a comment, as in SQL
}

#[test]
fn fraction_and_integer_literals_and_aggregates() {
    assert_eq!(p("a / FRAC(2, 3)"), b('/', c("a"), l(2, 3)));
    assert_eq!(p("a + FRAC(4, 2)"), b('+', c("a"), l(2, 1)));
    assert_eq!(parse_kind("a + FRAC(1, 0)"), Kind::Parse);
    assert_eq!(
        p("SUM(a*b)/COUNT(*)"),
        b('/', agg("SUM", Some(b('*', c("a"), c("b")))), agg("COUNT", None))
    );
    assert_eq!(p("AVG(a+1)*2"), b('*', agg("AVG", Some(b('+', c("a"), l(1, 1)))), l(2, 1)));
    assert_eq!(p("t.a*t.b"), b('*', c("t.a"), c("t.b")));
}

#[test]
fn malformed_expressions_are_parse_errors() {
    for t in [
        "a+", "(a", "a b", "a+*b", "sqrt(a)", "MIN(a)+1", "1+DOT(a,b)", "SUM(SUM(a))", "SUM(a+COUNT(*))", "COUNT(a)", "a,", "", "a/",
        "SUM()", "a;", "'x'", "a % b", "a ^ b", "FROM", "a FROM t", "a AS b",
    ] {
        assert_eq!(parse_kind(t), Kind::Parse, "{:?}", t);
    }
}

#[test]
fn the_expression_height_is_bounded_and_deep_input_cannot_overflow_the_stack() {
    p(&format!("a{}", "+a".repeat(98))); // height 98: fine
    assert_eq!(MAX_EXPR_HEIGHT, 100);
    let deep = |t: String| {
        let e = parse_expression(&t).expect_err("too deep");
        assert!(e.kind == Kind::Parse && e.message.contains("nested too deeply"), "{}", e);
    };
    deep(format!("{}a", "a+".repeat(200)));
    deep(format!("{}a{}{}", "(".repeat(150), ")".repeat(150), " + a".repeat(150)));
    deep(format!("{}a", "- ".repeat(300)));
    deep(format!("{}a", "(".repeat(100000)));
    deep(format!("{}a", "- ".repeat(100000)));
    deep(format!("{}a", "SUM(".repeat(1000)));
}

#[test]
fn render_round_trips_through_the_parser() {
    let mut seed: u64 = 5;
    let mut rnd = move || {
        seed = (seed.wrapping_mul(6364136223846793005).wrapping_add(1442695040888963407)) >> 33;
        seed as usize
    };
    fn gen(d: usize, rnd: &mut dyn FnMut() -> usize) -> Expr {
        if d == 0 || rnd() % 5 < 1 {
            return match rnd() % 4 {
                0 => c("a"),
                1 => c("b"),
                2 => c("t.c"),
                _ => l([2, 7, -3][rnd() % 3], 1),
            };
        }
        if rnd() % 7 < 1 {
            return match gen(d - 1, rnd) {
                Expr::Lit(v) => Expr::Lit(v.neg()),
                x => neg(x),
            };
        }
        let op = ['+', '-', '*', '/'][rnd() % 4];
        let (x, y) = (gen(d - 1, rnd), gen(d - 1, rnd));
        b(op, x, y)
    }
    let mut checked = 0;
    for _ in 0..300 {
        let e = gen(4, &mut rnd);
        if matches!(e, Expr::Col(_) | Expr::Lit(_)) {
            continue;
        }
        let text = render_expr(&e);
        assert_eq!(render_expr(&p(&text)), text);
        checked += 1;
    }
    assert!(checked > 150, "{}", checked);
}

#[test]
fn constants_are_folded_exactly() {
    let r = resolver(vec![("t".into(), vec![col("p", "int", "paired")])]);
    let (e, _) = analyze_expression(&p("p / (1/3 + FRAC(1,6))"), &r).unwrap();
    assert_eq!(e, b('/', c("p"), l(1, 2)));
}

#[test]
fn the_vectors_file_is_the_one_the_python_generator_wrote() {
    let v = vec_json();
    assert!(v["comment"].is_string());
    assert!(v["exec"]["cases"].as_array().unwrap().len() > 400);
}
